  const clone=x=>JSON.parse(JSON.stringify(x)),obj=x=>x&&typeof x==='object'&&!Array.isArray(x)?x:{},str=(x,n=1000)=>typeof x==='string'?x.slice(0,n):'',own=(x,k)=>Object.hasOwn(x||{},k);
