  function sanitize(value,depth=0){if(depth>12)throw Error('记录嵌套过深。');if(value===null||typeof value==='boolean')return value;if(typeof value==='number'){if(!Number.isFinite(value))throw Error('数额应为有效数字。');return value;}if(typeof value==='string'){if(value.length>4000)throw Error('单条文字过长，请摘要续记。');return value;}if(Array.isArray(value)){if(value.length>100)throw Error('单次列表过长。');return value.map(v=>sanitize(v,depth+1));}if(typeof value==='object'){const a={};for(const[k,v]of Object.entries(value)){if(!safe(k))throw Error('记录中含有保留字段。');a[k]=sanitize(v,depth+1);}return a;}throw Error('记录包含不支持的值。');}
