    if(!num(t.金额)||t.金额===0||!assets.has(t.币种)||!clock(t.日期)||!str(t.依据)||!str(t.事项))throw Error('流水需要日期、实际事项、依据、正整数金额与独立币种。');
    const signature=r=>JSON.stringify(['日期','类型','币种','金额','转出','转入','事项','依据'].map(k=>r[k]??''));
    if(Object.values(x.流水).some(r=>signature(r)===signature(t)))throw Error('相同收支凭据已入账，不能换编号再领。');
    if(!['收入','支出','内转'].includes(t.类型))throw Error('预算、预期利润不作流水。');
    if(t.类型==='收入'&&(!t.转入||t.转出)||t.类型==='支出'&&(!t.转出||t.转入)||t.类型==='内转'&&(!t.转入||!t.转出||t.转入===t.转出))throw Error('收支方向有误。');
