        if(k==='新闻'){if(!str(row.标题)||!str(row.正文)||!clock(row.日期))throw Error('新闻须有标题、正文与故事日期。');if(!['渡口','报社','家宅','朝堂','商市','江防','无'].includes(row.图类||'无'))row.图类='无';if(time&&clock(row.日期).key>time.key)throw Error('尚未发生的新闻不能提前刊行。');}
