  const chineseDay=d=>d<=10?['','初一','初二','初三','初四','初五','初六','初七','初八','初九','初十'][d]:d<20?'十'+['','一','二','三','四','五','六','七','八','九'][d-10]:d===20?'二十':d<30?'廿'+['','一','二','三','四','五','六','七','八','九'][d-20]:d===30?'三十':'卅一';
