  function appointments(){return C.appointments(X,S.year||time?.y||3726,S.month||time?.m||12);}
  function upcoming(){const y=time?.y||S.year,m=time?.m||S.month,a=C.appointments(X,y,m),b=C.appointments(X,m===12?y+1:y,m===12?1:m+1);return [...new Map([...a,...b].map(t=>[t.id,t])).values()].sort((a,b)=>String(a.日期||'').localeCompare(String(b.日期||'')));}
  function saveUI(){options.saveUI?.({...S,form:false});}
  function header(){const v=S.closed?'home':S.view,title={home:'咫尺天涯',news:'离阳邸闻',factions:'往来牒',family:'谢门家业',calendar:'岁时簿',settings:'灯下设定'}[v],sub={home:'城中有风声，灯下有家书。',news:'大小见闻，尽在一纸之间。',factions:'来帖有温凉，往来有分寸。',family:'一门灯火，寸缕家业。',calendar:'把牵挂的事，留在这一页。',settings:'落笔有分工，灯火各归处。'}[v];return '<header class="banner '+(v==='home'?'home-banner':'has-return')+'">'+(v==='home'?'':button('归案','data-go="home" aria-label="返回灯下总览"','return-seal'))+'<div class="brand"><div class="eyebrow">离阳 · 谢门灯火</div>'+(v==='home'?'<h1 class="logo"><img class="wordmark" src="data:image/webp;base64," alt="咫尺天涯"></h1>':'<h1>'+title+'</h1>')+'<p>'+sub+'</p></div><div class="date-slip"><small>'+(time?time.y+'年 · '+time.m+'月':'元会历')+'</small><strong>'+(time?chineseDay(time.d):'待核')+'</strong><span>'+hour()+'</span></div><div class="header-tools">'+link('设置','data-go="settings" aria-label="打开更新设置"')+'</div><button type="button" class="pull-scroll cursor-interaction" data-fold aria-expanded="'+!S.closed+'" aria-label="'+(S.closed?'展开书卷':'收起书卷')+'">'+(S.closed?'展开书卷 ▾':'收卷 ▴')+'</button></header>';}
