  function newsView(){const news=C.news(X),n=news.find(n=>n.id===S.news)||news[0];return '<section class="sheet news-paper"><header class="newspaper-mast"><div><div class="kicker">'+(n?date(n.日期):'新刊待续')+' · 辰正刊</div><h2>离阳邸闻</h2></div><span class="muted">城中事，纸上闻。<br>先辨来处，再辨真假。</span>'+icon('news')+'</header><div class="news-columns"><article class="news-story">'+(n?'<div class="kicker">'+esc(n.类别||'市井见闻')+' · '+esc(n.核实||'未核')+'</div><h3>'+esc(n.标题)+'</h3><div class="muted">采自：'+esc(n.来源||'来处待核')+'</div>'+art(n.图类)+'<p>'+esc(n.正文)+'</p><p>'+esc(n.后续)+'</p><div class="actions">'+action(X.计事['news:'+n.id]?'取下这张夹页':'夹入岁时簿','data-clip="'+esc(n.id)+'"')+link('翻看计事','data-go="calendar"')+link('留待查访','data-draft-news="'+esc(n.id)+'"')+'</div>':empty('暂未收到刊载的消息。可以等正文带来新报，也可向报社问问今日的见闻。'))+'</article><aside class="news-sidelist"><h4>别页见闻</h4>'+news.filter(r=>r!==n).slice(0,15).map(x=>'<button type="button" class="news-choice" data-news="'+esc(x.id)+'"><div class="kicker">'+dateShort(x.日期)+' · '+esc(x.类别)+'</div><strong>'+esc(x.标题)+'</strong><span>'+esc(x.核实||'未核')+' · '+esc(x.来源)+'</span></button>').join('')+(!n?link('向报社问讯','data-ask="我想看看今日新出的邸闻，再听听报社有哪些值得留意的消息。"'):'')+'</aside></div><footer class="press-colophon"><span>传闻有来处，未核之事仍留一分余地。</span><span>'+ (C.due(X,time)?'辰正已过，本期消息待采':'新刊随故事日时续记')+'</span></footer></section>';}
