  function settingsView(){return '<section class="sheet settings-paper"><div class="kicker">更新分工 · 与道渊共存</div><h2>灯下如何续录</h2><p class="settings-intro">正文负责故事，扩展只记已经发生的事。原道渊的变量和状态栏继续照常工作。</p><fieldset><legend>选择更新方式</legend>'+[['body','随正文输出','正文回复一并续录，不再请求另一模型。'],['extra','随原 MVU 额外解析','共用原卡那一次解析；请在原 MVU 中启用“额外模型解析”。'],['api','独立 API','仅核对最近剧情，单独请求一次扩展更新。']].map(([v,label,desc])=>'<label class="mode-choice"><input type="radio" name="liyang-mode" value="'+v+'" '+(settings.mode===v?'checked':'')+'><span><strong>'+label+'</strong><small>'+desc+'</small></span></label>').join('')+'</fieldset><div class="api-fields"><label>API 地址<input name="api-url" type="url" autocomplete="off" placeholder="https://…/v1" value="'+esc(settings.url)+'"></label><label>模型名称<input name="api-model" autocomplete="off" value="'+esc(settings.model)+'"></label><label>API 密钥<input name="api-key" type="password" autocomplete="off" value="'+esc(settings.key)+'"></label><label>最大输出 token<input name="api-tokens" type="number" min="512" max="16000" value="'+settings.tokens+'"></label></div><label class="automatic"><input name="automatic" type="checkbox" '+(settings.automatic?'checked':'')+'> 独立 API 在新回复与原变量更新完成后自动核对</label><p class="muted">API 设置只保存在此浏览器，密钥不会写入聊天、世界书或交付包。界面不会代你发送正文行动。切换聊天或分支会放弃尚未落笔的请求。</p><div class="actions">'+action('保存设定','data-settings-save')+link('核对当前楼','data-update')+(busy?link('取消本次核对','data-cancel-update'):'')+link('清除密钥','data-clear-key')+'</div><p class="update-detail" role="status">'+esc(status)+'</p></section>';}
